import json,sys
t=json.load(open('/work/trace.json')); rows=t['rows']
MAXLEN=int(sys.argv[1]) if len(sys.argv)>1 else 16
class M:
    def reset(s):
        s.st='IDLE'; s.ones=0; s.sh=0; s.nb=0; s.cnt=0; s.ln=0
        s.data=0; s.dv=0; s.ok=0; s.bad=0; s.bytes=[]
    def step(s,rx):
        s.dv=s.ok=s.bad=0
        if s.st=='IDLE':
            if rx==0:
                s.st='LEN'; s.ones=0; s.nb=0; s.sh=0; s.bytes=[]
            return
        # destuff
        if s.ones==5:
            s.ones=0
            if rx==1:
                s.bad=1; s.st='IDLE'; s.ev=('stufferr',)
            return
        s.ones = s.ones+1 if rx else 0
        s.sh = (s.sh>>1)|(rx<<7); s.nb+=1
        if s.nb<8: return
        s.nb=0; b=s.sh
        if s.st=='LEN':
            s.ln=b; s.cnt=0
            if b==0 or b>MAXLEN:
                s.bad=1; s.st='IDLE'; s.ev=('badlen',b)
            else: s.st='DATA'
        elif s.st=='DATA':
            s.data=b; s.dv=1; s.cnt+=1; s.bytes.append(b)
            if s.cnt==s.ln: s.st='CHK'
        elif s.st=='CHK':
            s.ok=1; s.st='IDLE'; s.ev=('frame',s.ln,list(s.bytes),b)
m=M(); m.reset()
frames=[]
for i,r in enumerate(rows):
    out=(m.data,m.dv,m.ok|m.bad)
    exp=(r[2],r[3],r[4]|r[5]) if r[2]!='x' else None
    if exp is not None and i>0 and out!=exp:
        print('MISMATCH',i,out,exp); break
    if m.ok or m.bad: frames.append((i,m.ev,r[4],r[5]))
    if r[0]==1: m.reset()
    else: m.step(r[1])
for f in frames: print(*f)
